import React, { useEffect, useState } from 'react';
import api from "../api/axios";
import { useSelector } from 'react-redux';

const AdminDashboard = () => {
  const token = useSelector((state) => state.auth.token);
  const [tickets, setTickets] = useState([]);
  const [filterStatus, setFilterStatus] = useState('All'); // 'All', 'Open', 'In Progress', 'Closed'
  const [sortOrder, setSortOrder] = useState('desc'); // 'asc' or 'desc'

  useEffect(() => {
    const fetchTickets = async () => {
      try {
        const response = await api.get('/api/tickets/', {
          headers: { Authorization: `Bearer ${token}` },
        });
        setTickets(response.data);
      } catch (error) {
        console.error('Error fetching tickets:', error);
      }
    };
    fetchTickets();
  }, [token]);

  // Get unique statuses for the filter dropdown
  const statuses = ['All', ...new Set(tickets.map(t => t.status))];

  // Filter tickets by status
  const filteredTickets = tickets.filter(ticket =>
    filterStatus === 'All' ? true : ticket.status === filterStatus
  );

  // Sort tickets by priority (assuming priority is a number, e.g., 1=Low, 2=Medium, 3=High)
  const sortedTickets = [...filteredTickets].sort((a, b) => {
    const priorityA = a.priority;
    const priorityB = b.priority;
    return sortOrder === 'asc' ? priorityA - priorityB : priorityB - priorityA;
  });

  const toggleSort = () => {
    setSortOrder(prev => (prev === 'asc' ? 'desc' : 'asc'));
  };

  return (
    <div style={{ padding: '20px' }}>
      <h2>All Tickets</h2>

      {/* Filter and Sort Controls */}
      <div style={{ marginBottom: '20px', display: 'flex', gap: '20px', alignItems: 'center' }}>
        <div>
          <label style={{ marginRight: '10px' }}>Filter by Status: </label>
          <select
            value={filterStatus}
            onChange={(e) => setFilterStatus(e.target.value)}
          >
            {statuses.map(status => (
              <option key={status} value={status}>
                {status}
              </option>
            ))}
          </select>
        </div>

        <button onClick={toggleSort}>
          Sort by Priority ({sortOrder === 'asc' ? 'Low to High' : 'High to Low'})
        </button>
      </div>

      {/* Tickets Table */}
      <table style={{ width: '100%', borderCollapse: 'collapse' }}>
        <thead>
          <tr style={{ backgroundColor: '#f4f4f4' }}>
            <th style={{ padding: '10px', border: '1px solid #ddd' }}>Title</th>
            <th style={{ padding: '10px', border: '1px solid #ddd' }}>Creator</th>
            <th style={{ padding: '10px', border: '1px solid #ddd', cursor: 'pointer' }} onClick={toggleSort}>
              Priority {sortOrder === 'asc' ? '↑' : '↓'}
            </th>
            <th style={{ padding: '10px', border: '1px solid #ddd' }}>Status</th>
          </tr>
        </thead>
        <tbody>
          {sortedTickets.length === 0 ? (
            <tr>
              <td colSpan="4" style={{ textAlign: 'center', padding: '20px' }}>
                No tickets found
              </td>
            </tr>
          ) : (
            sortedTickets.map(ticket => (
              <tr key={ticket.id}>
                <td style={{ padding: '10px', border: '1px solid #ddd' }}>{ticket.title}</td>
                <td style={{ padding: '10px', border: '1px solid #ddd' }}>{ticket.creator?.email || 'N/A'}</td>
                <td style={{ padding: '10px', border: '1px solid #ddd' }}>{ticket.priority}</td>
                <td style={{ padding: '10px', border: '1px solid #ddd' }}>{ticket.status}</td>
              </tr>
            ))
          )}
        </tbody>
      </table>
    </div>
  );
};

export default AdminDashboard;
